-- 12 örnek ürün. Aynı SKU varsa atlanır; tekrar çalıştırmak güvenlidir.
INSERT INTO products (slug, sku, name, category, tagline, description, story, brand, origin, msrp_unit, case_price, case_size, min_cases, price_tiers, weight_lbs, dimensions, stock, lead_time_days, rating_x10, review_count, image, images, features, specs, badges, featured, active) VALUES
('daily-foundations-multivitamin', 'MSC-VIT-090', 'Daily Foundations Multivitamin', 'supplements', '90 capsules · 23 essential nutrients · case of 12 bottles', 'A single-SKU daily multivitamin built for the shelf: clean label, third-party tested, and priced for a healthy 55% retail margin. Methylated B12 and chelated minerals for absorption, with no titanium dioxide or artificial dyes.

Every case ships with a lot-matched Certificate of Analysis and a printable shelf-talker. NSF Certified for Sport and produced in an FDA-registered, cGMP facility in Pennsylvania.', 'Meridian Labs was founded in 2016 by two compounding pharmacists who were tired of watching independent retailers overpay for private-label vitamins. Daily Foundations is still our volume leader — over 1.4 million bottles shipped to independent pharmacies, gyms and grocery accounts.', 'Meridian Labs', 'Pittsburgh, PA', 2499, 11880, 12, 1, '[{"minCases":2,"casePrice":11286},{"minCases":5,"casePrice":10692},{"minCases":10,"casePrice":9979}]'::jsonb, 14, '{"l":16,"w":12,"h":9}'::jsonb, 186, 2, 45, 0, '/images/prod-multivitamin.jpg', '["/images/prod-multivitamin.jpg","/images/cat-supplements.jpg","/images/hero-warehouse.jpg"]'::jsonb, '["23 nutrients including methylated B12 and 400 mcg folate","NSF Certified for Sport · cGMP facility","Lot-matched CoA in every case","Retail-ready bottle with security seal and shelf-talker"]'::jsonb, '[{"label":"Units per case","value":"12 bottles · 90 capsules each"},{"label":"Suggested retail","value":"$24.99 / bottle"},{"label":"Shelf life","value":"24 months from manufacture"},{"label":"Certifications","value":"NSF Certified for Sport, Non-GMO"},{"label":"Case weight / dims","value":"14 lb · 16 × 12 × 9 in"}]'::jsonb, '["Best seller","NSF certified"]'::jsonb, true, true),
('omega-3-ultra-1200', 'MSC-OM3-120', 'Omega-3 Ultra 1200mg', 'supplements', '120 softgels · IFOS 5-star fish oil · case of 12 bottles', 'Molecularly distilled wild-caught anchovy and sardine oil delivering 720 mg EPA and 480 mg DHA per serving. IFOS 5-star rated for purity and heavy-metal testing, with a natural lemon coating that keeps the fishiness off the shelf.

Ships in a nitrogen-flushed HDPE bottle with induction seal. Batch documentation and IFOS certificates are available on request for retail compliance files.', 'Sourced from a Peruvian anchovy fishery audited yearly against IFFO standards, then soft-gel encapsulated in New Jersey within 30 days of catch. The result is a lower oxidation value than most premium grocery brands — and a price your buyers can actually margin.', 'Meridian Labs', 'Newark, NJ', 3999, 20160, 12, 1, '[{"minCases":2,"casePrice":19152},{"minCases":5,"casePrice":18144},{"minCases":10,"casePrice":16934}]'::jsonb, 16, '{"l":15,"w":11,"h":8}'::jsonb, 92, 2, 45, 0, '/images/prod-omega.jpg', '["/images/prod-omega.jpg","/images/cat-supplements.jpg"]'::jsonb, '["1,200 mg total omega-3 per serving","IFOS 5-star purity rating","Nitrogen-flushed induction seal","Traceable to a single fishery"]'::jsonb, '[{"label":"Units per case","value":"12 bottles · 120 softgels each"},{"label":"Suggested retail","value":"$39.99 / bottle"},{"label":"Shelf life","value":"24 months"},{"label":"Certifications","value":"IFOS 5-star, Friend of the Sea"},{"label":"Case weight / dims","value":"16 lb · 15 × 11 × 8 in"}]'::jsonb, '["IFOS 5-star"]'::jsonb, true, true),
('elderberry-immune-gummies', 'MSC-ELD-060', 'Elderberry Immune Gummies', 'supplements', '60 gummies · pectin-based, vegan · case of 24', 'Black elderberry, zinc and vitamin C in a pectin gummy that ships well and sells fast at the register. Vegan, gelatin-free, and naturally coloured with carrot and blackcurrant — a real differentiator against the neon gummy wall.

High case count keeps the per-unit freight low, which makes this our most requested impulse item for checkout racks and gift baskets.', 'We built this SKU with an organic elderberry co-operative in Oregon, using a low-temperature extraction that keeps the anthocyanin content high. It is the fastest-turning supplement we carry among grocery and gift accounts.', 'Meridian Botanicals', 'Eugene, OR', 1899, 19176, 24, 1, '[{"minCases":2,"casePrice":18217},{"minCases":5,"casePrice":17258},{"minCases":10,"casePrice":16108}]'::jsonb, 18, '{"l":18,"w":12,"h":10}'::jsonb, 7, 2, 45, 0, 'https://images.pexels.com/photos/14029290/pexels-photo-14029290.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/14029290/pexels-photo-14029290.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940","/images/cat-supplements.jpg"]'::jsonb, '["Pectin-based, vegan and gelatin-free","1,000 mg elderberry extract per serving","High case count for low landed freight","Counter display shipper available on request"]'::jsonb, '[{"label":"Units per case","value":"24 bottles · 60 gummies each"},{"label":"Suggested retail","value":"$18.99 / bottle"},{"label":"Shelf life","value":"18 months"},{"label":"Certifications","value":"Vegan, Non-GMO Project"},{"label":"Case weight / dims","value":"18 lb · 18 × 12 × 10 in"}]'::jsonb, '["Low stock","Impulse buy"]'::jsonb, false, true),
('magnesium-glycinate-400', 'MSC-MAG-120', 'Magnesium Glycinate 400', 'supplements', '120 capsules · fully chelated · case of 12', 'Fully chelated magnesium bisglycinate with no magnesium oxide filler. Gentle on digestion, popular for sleep and recovery, and one of the highest-margin supplements on a modern wellness shelf.

Capsules are vegetarian and the bottle uses a wide-mouth 45 mm closure that takes standard security caps.', 'Our most repurchased SKU by pharmacy and recovery-studio accounts. We hold three months of buffer stock on the raw material so our case price does not swing with the mineral market.', 'Meridian Labs', 'Pittsburgh, PA', 2299, 12960, 12, 1, '[{"minCases":2,"casePrice":12312},{"minCases":5,"casePrice":11664},{"minCases":10,"casePrice":10886}]'::jsonb, 13, '{"l":15,"w":11,"h":8}'::jsonb, 140, 2, 45, 0, '/images/cat-supplements.jpg', '["/images/cat-supplements.jpg","/images/prod-multivitamin.jpg"]'::jsonb, '["400 mg elemental magnesium per serving","Zero oxide or citrate fillers","Vegetarian capsule, no excipients","Three-month raw material buffer"]'::jsonb, '[{"label":"Units per case","value":"12 bottles · 120 capsules each"},{"label":"Suggested retail","value":"$22.99 / bottle"},{"label":"Shelf life","value":"24 months"},{"label":"Certifications","value":"cGMP, Non-GMO"},{"label":"Case weight / dims","value":"13 lb · 15 × 11 × 8 in"}]'::jsonb, '["Top rated"]'::jsonb, true, true),
('estate-extra-virgin-olive-oil', 'MSC-PAN-OO1L', 'Estate Extra Virgin Olive Oil', 'pantry', '1 L dark glass · early harvest · case of 6', 'Single-estate Picual olive oil pressed within six hours of harvest, with a peppery finish and a polyphenol count printed on every lot. Dark glass protects the oil from light damage during retail display.

Case of six with moulded pulp dividers. This is the anchor SKU for pantry resets and gift assortments, and pairs naturally with our honey and pasta for consolidated freight.', 'We buy directly from a 220-hectare estate near Jaén, Spain, on a fixed-price forward contract. That lets us publish a stable case price through the year while independent grocers still retail it at $28.99.', 'Casa Meridian', 'Jaén, Spain', 2899, 8940, 6, 1, '[{"minCases":2,"casePrice":8493},{"minCases":5,"casePrice":8046},{"minCases":10,"casePrice":7510}]'::jsonb, 22, '{"l":14,"w":10,"h":12}'::jsonb, 74, 2, 45, 0, '/images/prod-oliveoil.jpg', '["/images/prod-oliveoil.jpg","/images/cat-pantry.jpg"]'::jsonb, '["Early-harvest Picual, cold extracted","Polyphenol count printed per lot","Dark glass with moulded pulp shippers","Food-service 3 L format available on request"]'::jsonb, '[{"label":"Units per case","value":"6 × 1 L bottles"},{"label":"Suggested retail","value":"$28.99 / bottle"},{"label":"Shelf life","value":"18 months"},{"label":"Harvest","value":"2026 early harvest"},{"label":"Case weight / dims","value":"22 lb · 14 × 10 × 12 in"}]'::jsonb, '["Harvest 2026","Best seller"]'::jsonb, true, true),
('raw-wildflower-honey', 'MSC-PAN-HNY16', 'Raw Wildflower Honey', 'pantry', '16 oz glass · unfiltered · case of 12', 'Unfiltered, uncooked wildflower honey from small apiaries in the Hudson Valley. Natural crystallisation is left intact — a quality signal, not a defect, though we include shelf cards to explain it to shoppers.

Glass jars with food-grade lined lids, packed 12 per case in a two-layer shipper that survives parcel handling.', 'We aggregate from eleven family apiaries, which keeps the flavour profile consistent year to year while supporting pollinator habitat across the Northeast.', 'Meridian Pantry', 'Hudson Valley, NY', 1799, 10560, 12, 1, '[{"minCases":2,"casePrice":10032},{"minCases":5,"casePrice":9504},{"minCases":10,"casePrice":8870}]'::jsonb, 20, '{"l":15,"w":11,"h":9}'::jsonb, 58, 2, 45, 0, '/images/prod-honey.jpg', '["/images/prod-honey.jpg","/images/cat-pantry.jpg"]'::jsonb, '["Raw, unfiltered, never heated","Aggregated from eleven family apiaries","Two-layer retail shipper included","Plastic-free packaging"]'::jsonb, '[{"label":"Units per case","value":"12 × 16 oz jars"},{"label":"Suggested retail","value":"$17.99 / jar"},{"label":"Shelf life","value":"36 months"},{"label":"Certifications","value":"True Source Honey verified"},{"label":"Case weight / dims","value":"20 lb · 15 × 11 × 9 in"}]'::jsonb, '["Small batch"]'::jsonb, false, true),
('single-origin-coffee-whole-bean', 'MSC-PAN-CFE2', 'Single-Origin Coffee, Whole Bean', 'pantry', '2 lb valve bag · Huila, Colombia · case of 6', 'Washed Caturra and Colombia varietals from Huila, roasted to a full-city profile that works in batch brew and espresso. Degassed and packed in a one-way valve bag with a roast date stamp, 2 lb per bag for the take-home bean crowd.

Roasted to order every Tuesday. Case of six with a 21-day freshness window — order freight early in the week for the freshest landed date.', 'Direct-trade relationship since 2019 with a 34-member co-operative. Pricing is transparent: we publish the FOB price we pay, and our case price moves only when the harvest does.', 'Meridian Roasting', 'Huila, Colombia', 3199, 11100, 6, 1, '[{"minCases":2,"casePrice":10545},{"minCases":5,"casePrice":9990},{"minCases":10,"casePrice":9324}]'::jsonb, 15, '{"l":14,"w":10,"h":8}'::jsonb, 63, 2, 45, 0, 'https://images.pexels.com/photos/17077385/pexels-photo-17077385.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/17077385/pexels-photo-17077385.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940","/images/cat-pantry.jpg"]'::jsonb, '["Direct-trade Huila co-operative","Roasted to order every Tuesday","One-way valve bag with roast date","Whole bean, full-city profile"]'::jsonb, '[{"label":"Units per case","value":"6 × 2 lb bags"},{"label":"Suggested retail","value":"$31.99 / bag"},{"label":"Freshness window","value":"21 days from roast"},{"label":"Roast","value":"Full city · whole bean"},{"label":"Case weight / dims","value":"15 lb · 14 × 10 × 8 in"}]'::jsonb, '["Roasted to order"]'::jsonb, true, true),
('bronze-die-artisan-pasta', 'MSC-PAN-PST5', 'Bronze-Die Artisan Pasta', 'pantry', '500 g bag · slow dried · case of 12', 'Durum semolina pasta extruded through bronze dies and slow dried for a rough, sauce-gripping surface. Retail-ready kraft window bag with a clear cooking-time panel.

The highest turn on our pantry line: low case price, small footprint, and a natural add-on to olive oil and honey orders.', 'Made in a fourth-generation pastificio outside Gragnano using the same slow-dry method the family has used since 1958. We import in full containers to keep landed case costs flat.', 'Meridian Pantry', 'Gragnano, Italy', 999, 5940, 12, 1, '[{"minCases":2,"casePrice":5643},{"minCases":5,"casePrice":5346},{"minCases":10,"casePrice":4990}]'::jsonb, 18, '{"l":16,"w":12,"h":8}'::jsonb, 121, 2, 45, 0, 'https://images.pexels.com/photos/38802734/pexels-photo-38802734.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/38802734/pexels-photo-38802734.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940","/images/cat-pantry.jpg"]'::jsonb, '["Bronze-die extruded for sauce adhesion","Slow dried at low temperature","Kraft window retail bag","Flat landed cost via full-container imports"]'::jsonb, '[{"label":"Units per case","value":"12 × 500 g bags"},{"label":"Suggested retail","value":"$9.99 / bag"},{"label":"Shelf life","value":"24 months"},{"label":"Certifications","value":"IGP Gragnano"},{"label":"Case weight / dims","value":"18 lb · 16 × 12 × 8 in"}]'::jsonb, '["High turn"]'::jsonb, false, true),
('hand-thrown-stoneware-vase', 'MSC-HOM-VAS1', 'Hand-Thrown Stoneware Vase', 'home', 'Sand glaze · 9 in · case of 4', 'Wheel-thrown stoneware in a speckled sand glaze, 9 inches tall with a narrow neck for single-stem styling. Each piece is slightly different — we photograph categories, not exact pieces, and ship the group shot to your web team on request.

Case of four with moulded pulp corner protection. Breakage in transit is covered at 100% on this SKU with photo documentation.', 'Thrown by a six-potter studio in western North Carolina. Capacity is limited to roughly 400 cases a month, and we hold allocation for accounts that reorder quarterly.', 'Meridian Home', 'Asheville, NC', 6800, 11600, 4, 1, '[{"minCases":2,"casePrice":11020},{"minCases":5,"casePrice":10440},{"minCases":10,"casePrice":9860}]'::jsonb, 14, '{"l":18,"w":14,"h":14}'::jsonb, 39, 2, 45, 0, '/images/prod-vase.jpg', '["/images/prod-vase.jpg","/images/cat-home.jpg"]'::jsonb, '["Wheel-thrown, speckled sand glaze","9 in tall · watertight interior","Moulded pulp corner protection","100% transit breakage cover with photos"]'::jsonb, '[{"label":"Units per case","value":"4 vases"},{"label":"Suggested retail","value":"$68.00 / vase"},{"label":"Dimensions","value":"9 in H × 5 in W"},{"label":"Material","value":"High-fire stoneware, food-safe glaze"},{"label":"Case weight / dims","value":"14 lb · 18 × 14 × 14 in"}]'::jsonb, '["Small batch","Breakage covered"]'::jsonb, true, true),
('amber-soy-candle', 'MSC-HOM-CDL8', 'Amber Soy Candle, Cedar & Fig', 'home', '8 oz amber glass · 45 hr burn · case of 12', 'Coconut-soy wax in an amber apothecary jar with a cotton wick and 45-hour burn time. Cedar & fig is the best-testing scent we have run — warm, not sweet, and safe for unisex gifting tables.

Case of twelve with a printed tester card. Also available in a 4-SKU scent assortment on request.', 'Poured in small batches in a Brooklyn workshop. We keep three scents on the wholesale line and rotate a seasonal fourth for Q4 gifting programs.', 'Meridian Home', 'Brooklyn, NY', 1600, 7800, 12, 1, '[{"minCases":2,"casePrice":7410},{"minCases":5,"casePrice":7020},{"minCases":10,"casePrice":6552}]'::jsonb, 12, '{"l":14,"w":10,"h":8}'::jsonb, 84, 2, 45, 0, '/images/prod-candle.jpg', '["/images/prod-candle.jpg","/images/cat-home.jpg"]'::jsonb, '["Coconut-soy wax, cotton wick","45-hour burn time","Amber apothecary glass with lid","Printed tester card in every case"]'::jsonb, '[{"label":"Units per case","value":"12 × 8 oz candles"},{"label":"Suggested retail","value":"$16.00 / candle"},{"label":"Scent","value":"Cedar & fig"},{"label":"Burn time","value":"45 hours"},{"label":"Case weight / dims","value":"12 lb · 14 × 10 × 8 in"}]'::jsonb, '["Gifting"]'::jsonb, false, true),
('boucle-lounge-chair', 'MSC-HOM-CHR1', 'Bouclé Lounge Chair', 'home', 'Solid ash frame · ivory bouclé · 1 per carton', 'A low-slung lounge chair in ivory bouclé over a solid ash frame, shipped fully assembled in a single carton. Designed as an anchor piece for boutique hotel lobbies and furniture floors.

At 48 lb and 30 × 30 × 26 in this SKU is billed on dimensional freight weight and typically ships LTL on a pallet with other home goods. Request a freight quote at checkout — our engine prices parcel and LTL side by side.', 'Made to our spec in a family-run upholstery shop in Hickory, North Carolina. Minimum order is one carton, but freight economics favour a 4-piece pallet build.', 'Meridian Home', 'Hickory, NC', 64900, 28900, 1, 1, '[{"minCases":2,"casePrice":27450},{"minCases":4,"casePrice":26000},{"minCases":8,"casePrice":24900}]'::jsonb, 48, '{"l":30,"w":30,"h":26}'::jsonb, 22, 2, 45, 0, 'https://images.pexels.com/photos/5793641/pexels-photo-5793641.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/5793641/pexels-photo-5793641.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940","/images/cat-home.jpg"]'::jsonb, '["Solid ash frame, webbed suspension","Performance bouclé, 50k rub count","Ships fully assembled in one carton","LTL pallet pricing at checkout"]'::jsonb, '[{"label":"Units per carton","value":"1 chair"},{"label":"Suggested retail","value":"$649.00 / chair"},{"label":"Dimensions","value":"30 in H × 30 in W × 26 in D"},{"label":"Material","value":"Ivory bouclé, solid ash"},{"label":"Carton weight / dims","value":"48 lb · 30 × 30 × 26 in"}]'::jsonb, '["LTL freight"]'::jsonb, false, true),
('dried-botanical-stems', 'MSC-HOM-STM12', 'Dried Botanical Stems', 'home', 'Natural bunch · 18 in · case of 12', 'A natural dried bunch that turns a single vase into a $95 vignette. Colour-fast, no shedding, and light enough to ride free on most parcel orders.

One bunch per sleeve, 12 sleeves per case. Pairs as a margin multiplier with the stoneware vase SKU.', 'Air-dried and hand-bundled in California from a flower farm that pivoted to dried goods during the import crunch of 2021. It has been a staple ever since.', 'Meridian Home', 'Carpinteria, CA', 1400, 6600, 12, 1, '[{"minCases":2,"casePrice":6270},{"minCases":5,"casePrice":5940},{"minCases":10,"casePrice":5544}]'::jsonb, 6, '{"l":24,"w":8,"h":8}'::jsonb, 46, 2, 45, 0, 'https://images.pexels.com/photos/38908537/pexels-photo-38908537.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940', '["https://images.pexels.com/photos/38908537/pexels-photo-38908537.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=650&w=940","/images/cat-home.jpg"]'::jsonb, '["Air-dried, colour-fast, non-shedding","18 in bunch, sleeved individually","Attaches naturally to vase SKU","Lightweight freight profile"]'::jsonb, '[{"label":"Units per case","value":"12 sleeved bunches"},{"label":"Suggested retail","value":"$14.00 / bunch"},{"label":"Length","value":"18 in"},{"label":"Material","value":"Natural dried botanicals"},{"label":"Case weight / dims","value":"6 lb · 24 × 8 × 8 in"}]'::jsonb, '["Add-on"]'::jsonb, false, true)
ON CONFLICT DO NOTHING;
